 16	// fakeRepo is a minimal Repository so the service can be tested without the store package.
 17	type fakeRepo struct {
 18		mu sync.Mutex
 19		m  map[string]Payment
 20	}
 21	
 22	func newFakeRepo() *fakeRepo { return &fakeRepo{m: map[string]Payment{}} }
 23	
 24	func (r *fakeRepo) Create(_ context.Context, p Payment) error {
 25		r.mu.Lock()
 26		defer r.mu.Unlock()
 27		r.m[p.ID] = p.Clone()
 28		return nil
 29	}
 30	
 31	func (r *fakeRepo) Get(_ context.Context, id string) (Payment, error) {
 32		r.mu.Lock()
 33		defer r.mu.Unlock()
 34		p, ok := r.m[id]
 35		if !ok {
 36			return Payment{}, fmt.Errorf("%w: %s", ErrNotFound, id)
 37		}
 38		return p.Clone(), nil
 39	}
 40	
 41	func (r *fakeRepo) Update(_ context.Context, p Payment) error {
 42		r.mu.Lock()
 43		defer r.mu.Unlock()
 44		cur, ok := r.m[p.ID]
 45		if !ok {
 46			return fmt.Errorf("%w: %s", ErrNotFound, p.ID)
 47		}
 48		if cur.Version != p.Version {
 49			return ErrVersionConflict
 50		}
 51		p = p.Clone()
 52		p.Version++
 53		r.m[p.ID] = p
 54		return nil
 55	}
