 73	func newTestService() (*Service, *recorder) {
 74		rec := &recorder{}
 75		clk := clock.NewFake(time.Date(2026, 3, 1, 12, 0, 0, 0, time.UTC))
 76		return NewService(newFakeRepo(), clk, NewSeqIDs(), rec, Config{FeeBps: 290}), rec
