 96	func TestCreateValidation(t *testing.T) {
 97		s, _ := newTestService()
 98		tests := []struct {
 99			name string
100			in   CreateInput
101		}{
102			{"missing merchant", CreateInput{Amount: money.MustNew(100, "USD")}},
103			{"zero amount", CreateInput{MerchantID: "m", Amount: money.MustNew(0, "USD")}},
104			{"negative amount", CreateInput{MerchantID: "m", Amount: money.MustNew(-1, "USD")}},
105		}
106		for _, tt := range tests {
107			t.Run(tt.name, func(t *testing.T) {
108				if _, err := s.Create(context.Background(), tt.in); !errors.Is(err, ErrInvalidInput) {
109					t.Fatalf("error = %v, want ErrInvalidInput", err)
110				}
111			})
112		}
113	}
