200	func TestPartialThenFullRefund(t *testing.T) {
201		s, rec := newTestService()
202		ctx := context.Background()
203		p := succeeded(t, s, 1000)
204	
205		p, r1, err := s.Refund(ctx, p.ID, money.MustNew(300, "USD"))
206		if err != nil {
207			t.Fatal(err)
208		}
209		if p.Status != StatusSucceeded || p.Refunded != 300 || r1.Amount.Minor != 300 {
210			t.Fatalf("after partial: status %s refunded %d", p.Status, p.Refunded)
211		}
212		p, _, err = s.Refund(ctx, p.ID, money.MustNew(700, "USD"))
213		if err != nil {
214			t.Fatal(err)
215		}
216		if p.Status != StatusRefunded || p.Refunded != 1000 || len(p.Refunds) != 2 {
217			t.Fatalf("after full: status %s refunded %d refunds %d", p.Status, p.Refunded, len(p.Refunds))
218		}
219		if last := rec.events[len(rec.events)-1]; last != "payment.refunded" {
220			t.Fatalf("last event = %s", last)
221		}
222	}
