  1	// Package store provides repository implementations for the payment domain.
  2	package store
  3	
  4	import (
  5		"context"
  6		"encoding/base64"
  7		"fmt"
  8		"strconv"
  9		"strings"
 10		"sync"
 11	
 12		"example.com/gopayments/payment"
 13	)
 14	
 15	const (
 16		defaultLimit = 20
 17		maxLimit     = 100
 18	)
 19	
 20	// Memory is an in-memory payment.Repository used in tests and local runs.
 21	type Memory struct {
 22		mu         sync.RWMutex
 23		byID       map[string]payment.Payment
 24		byMerchant map[string][]string // payment ids in creation order
 25	}
 26	
 27	var _ payment.Repository = (*Memory)(nil)
 28	
 29	// NewMemory returns an empty repository.
 30	func NewMemory() *Memory {
 31		return &Memory{
 32			byID:       make(map[string]payment.Payment),
 33			byMerchant: make(map[string][]string),
 34		}
 35	}
 36	
 37	// Create stores a new payment.
 38	func (m *Memory) Create(_ context.Context, p payment.Payment) error {
 39		m.mu.Lock()
 40		defer m.mu.Unlock()
 41		if _, ok := m.byID[p.ID]; ok {
 42			return fmt.Errorf("%w: %s", payment.ErrDuplicate, p.ID)
 43		}
 44		m.byID[p.ID] = p.Clone()
 45		m.byMerchant[p.MerchantID] = append(m.byMerchant[p.MerchantID], p.ID)
 46		return nil
 47	}
 48	
 49	// Get returns a copy of the stored payment.
 50	func (m *Memory) Get(_ context.Context, id string) (payment.Payment, error) {
 51		m.mu.RLock()
 52		defer m.mu.RUnlock()
 53		p, ok := m.byID[id]
 54		if !ok {
 55			return payment.Payment{}, fmt.Errorf("%w: %s", payment.ErrNotFound, id)
 56		}
 57		return p.Clone(), nil
 58	}
 59	
 60	// Update replaces the stored payment if versions match.
 61	func (m *Memory) Update(_ context.Context, p payment.Payment) error {
 62		m.mu.Lock()
 63		defer m.mu.Unlock()
 64		cur, ok := m.byID[p.ID]
 65		if !ok {
 66			return fmt.Errorf("%w: %s", payment.ErrNotFound, p.ID)
 67		}
 68		if cur.Version != p.Version {
 69			return fmt.Errorf("%w: payment %s has version %d, update based on %d", payment.ErrVersionConflict, p.ID, cur.Version, p.Version)
 70		}
 71		next := p.Clone()
 72		next.Version++
 73		m.byID[p.ID] = next
 74		return nil
 75	}
 76	
 77	// ListByMerchant pages through a merchant's payments in creation order.
 78	func (m *Memory) ListByMerchant(_ context.Context, merchantID string, page payment.Page) ([]payment.Payment, string, error) {
 79		limit := page.Limit
 80		switch {
 81		case limit < 0:
 82			return nil, "", fmt.Errorf("%w: limit must not be negative", payment.ErrInvalidInput)
 83		case limit == 0:
 84			limit = defaultLimit
 85		case limit > maxLimit:
 86			limit = maxLimit
 87		}
 88		offset := 0
 89		if page.Cursor != "" {
 90			var err error
 91			if offset, err = decodeCursor(page.Cursor); err != nil {
 92				return nil, "", err
 93			}
 94		}
 95	
 96		m.mu.RLock()
 97		defer m.mu.RUnlock()
 98		ids := m.byMerchant[merchantID]
 99		if offset > len(ids) {
100			offset = len(ids)
101		}
102		end := min(offset+limit, len(ids))
103		out := make([]payment.Payment, 0, end-offset)
104		for _, id := range ids[offset:end] {
105			out = append(out, m.byID[id].Clone())
106		}
107		next := ""
108		if end < len(ids) {
109			next = encodeCursor(end)
110		}
111		return out, next, nil
112	}
113	
114	func encodeCursor(offset int) string {
115		return base64.RawURLEncoding.EncodeToString([]byte("o:" + strconv.Itoa(offset)))
116	}
117	
118	func decodeCursor(c string) (int, error) {
119		raw, err := base64.RawURLEncoding.DecodeString(c)
120		if err != nil {
121			return 0, fmt.Errorf("%w: %v", payment.ErrInvalidCursor, err)
122		}
123		n, ok := strings.CutPrefix(string(raw), "o:")
124		if !ok {
125			return 0, fmt.Errorf("%w: unexpected format", payment.ErrInvalidCursor)
126		}
127		off, err := strconv.Atoi(n)
128		if err != nil || off < 0 {
129			return 0, fmt.Errorf("%w: bad offset %q", payment.ErrInvalidCursor, n)
130		}
131		return off, nil
132	}

  1	package money
  2	
  3	import (
  4		"errors"
  5		"fmt"
  6		"math"
  7		"strconv"
  8		"strings"
  9	)
 10	
 11	var (
 12		// ErrInvalidAmount is returned for malformed or out-of-range amounts.
 13		ErrInvalidAmount = errors.New("invalid amount")
 14		// ErrPrecision is returned when an amount has more decimals than its currency allows.
 15		ErrPrecision = errors.New("too many decimal places for currency")
 16		// ErrCurrencyMismatch is returned when combining amounts in different currencies.
 17		ErrCurrencyMismatch = errors.New("currency mismatch")
 18	)
 19	
 20	// Amount is an exact quantity of money in minor units.
 21	type Amount struct {
 22		Minor    int64
 23		Currency Currency
 24	}
 25	
 26	// New builds an amount from minor units.
 27	func New(minor int64, code string) (Amount, error) {
 28		c, err := LookupCurrency(code)
 29		if err != nil {
 30			return Amount{}, err
 31		}
 32		return Amount{Minor: minor, Currency: c}, nil
 33	}
 34	
 35	// MustNew is New for tests and constants; it panics on unknown currencies.
 36	func MustNew(minor int64, code string) Amount {
 37		a, err := New(minor, code)
 38		if err != nil {
 39			panic(err)
 40		}
 41		return a
 42	}
 43	
 44	// Parse reads a decimal string in major units ("10.50") for the given currency.
 45	// More fractional digits than the currency exponent is an error, never rounded.
 46	func Parse(s, code string) (Amount, error) {
 47		cur, err := LookupCurrency(code)
 48		if err != nil {
 49			return Amount{}, err
 50		}
 51		s = strings.TrimSpace(s)
 52		neg := strings.HasPrefix(s, "-")
 53		s = strings.TrimPrefix(s, "-")
 54		intPart, frac, hasDot := strings.Cut(s, ".")
 55		if intPart == "" || (hasDot && frac == "") || !digits(intPart) || !digits(frac) {
 56			return Amount{}, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
 57		}
 58		if len(frac) > cur.Exponent {
 59			return Amount{}, fmt.Errorf("%w: %s allows %d, got %q", ErrPrecision, cur.Code, cur.Exponent, s)
 60		}
 61		major, err := strconv.ParseInt(intPart, 10, 64)
 62		if err != nil || major > math.MaxInt64/cur.Factor() {
 63			return Amount{}, fmt.Errorf("%w: %q out of range", ErrInvalidAmount, s)
 64		}
 65		minor := major * cur.Factor()
 66		if frac != "" {
 67			frac += strings.Repeat("0", cur.Exponent-len(frac))
 68			f, err := strconv.ParseInt(frac, 10, 64)
 69			if err != nil {
 70				return Amount{}, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
 71			}
 72			minor += f
 73		}
 74		if neg {
 75			minor = -minor
 76		}
 77		return Amount{Minor: minor, Currency: cur}, nil
 78	}
 79	
 80	func digits(s string) bool {
 81		for _, r := range s {
 82			if r < '0' || r > '9' {
 83				return false
 84			}
 85		}
 86		return true
 87	}
 88	
 89	// Decimal renders the amount in major units with exactly Exponent decimals.
 90	func (a Amount) Decimal() string {
 91		m := a.Minor
 92		sign := ""
 93		if m < 0 {
 94			sign = "-"
 95			m = -m
 96		}
 97		if a.Currency.Exponent == 0 {
 98			return sign + strconv.FormatInt(m, 10)
 99		}
100		f := a.Currency.Factor()
101		return fmt.Sprintf("%s%d.%0*d", sign, m/f, a.Currency.Exponent, m%f)
102	}
103	
104	// String renders "10.50 USD".
105	func (a Amount) String() string { return a.Decimal() + " " + a.Currency.Code }
106	
107	// Add returns a+b; both must share a currency.
108	func (a Amount) Add(b Amount) (Amount, error) {
109		if a.Currency != b.Currency {
110			return Amount{}, fmt.Errorf("%w: %s + %s", ErrCurrencyMismatch, a.Currency.Code, b.Currency.Code)
111		}
112		return Amount{Minor: a.Minor + b.Minor, Currency: a.Currency}, nil
113	}
114	
115	// Sub returns a-b; both must share a currency.
116	func (a Amount) Sub(b Amount) (Amount, error) {
117		if a.Currency != b.Currency {
118			return Amount{}, fmt.Errorf("%w: %s - %s", ErrCurrencyMismatch, a.Currency.Code, b.Currency.Code)
119		}
120		return Amount{Minor: a.Minor - b.Minor, Currency: a.Currency}, nil
121	}
122	
123	// IsPositive reports whether the amount is strictly greater than zero.
124	func (a Amount) IsPositive() bool { return a.Minor > 0 }

