 1	package money
 2	
 3	import (
 4		"fmt"
 5		"sort"
 6	)
 7	
 8	// Allocate splits a into len(ratios) parts proportional to ratios, for example
 9	// to pay out one charge to several sub-merchants.
10	//
11	// Contract (reconciliation depends on it):
12	//   - the parts always sum exactly to a;
13	//   - every part differs from its exact proportional share by less than one
14	//     minor unit;
15	//   - leftover minor units go one each to the parts with the largest fractional
16	//     remainder, ties broken by lower index.
17	//
18	// a must be non-negative, ratios non-negative with a positive sum.
19	func Allocate(a Amount, ratios []int64) ([]Amount, error) {
20		if a.Minor < 0 {
21			return nil, fmt.Errorf("%w: cannot allocate negative amount %s", ErrInvalidAmount, a)
22		}
23		var total int64
24		for _, r := range ratios {
25			if r < 0 {
26				return nil, fmt.Errorf("%w: negative ratio %d", ErrInvalidAmount, r)
27			}
28			total += r
29		}
30		if total == 0 {
31			return nil, fmt.Errorf("%w: ratios must sum to a positive value", ErrInvalidAmount)
32		}
33	
34		parts := make([]Amount, len(ratios))
35		rems := make([]int64, len(ratios))
36		var assigned int64
37		for i, r := range ratios {
38			share := a.Minor * r
39			parts[i] = Amount{Minor: share / total, Currency: a.Currency}
40			rems[i] = share % total
41			assigned += parts[i].Minor
42		}
43	
44		order := make([]int, len(ratios))
45		for i := range order {
46			order[i] = i
47		}
48		sort.SliceStable(order, func(x, y int) bool { return rems[order[x]] > rems[order[y]] })
49		for i := int64(0); i < a.Minor-assigned; i++ {
50			parts[order[i]].Minor++
51		}
52		return parts, nil
53	}

