func TestRefundValidation(t *testing.T) {
	s, _ := newTestService()
	ctx := context.Background()
	p := succeeded(t, s, 1000)
	if _, _, err := s.Refund(ctx, p.ID, money.MustNew(0, "USD")); !errors.Is(err, ErrInvalidInput) {
		t.Errorf("zero refund: %v", err)
	}
	if _, _, err := s.Refund(ctx, p.ID, money.MustNew(10, "EUR")); !errors.Is(err, money.ErrCurrencyMismatch) {
		t.Errorf("currency mismatch: %v", err)
	}
	if _, _, err := s.Refund(ctx, p.ID, money.MustNew(1001, "USD")); !errors.Is(err, ErrRefundExceedsRemaining) {
		t.Errorf("over refund: %v", err)
	}
}

func TestPartialRefundRejectsExceedingRemaining(t *testing.T) {
	s, rec := newTestService()
	ctx := context.Background()
	p := succeeded(t, s, 100000)

	p, _, err := s.Refund(ctx, p.ID, money.MustNew(60000, "USD"))
	if err != nil {
		t.Fatal(err)
	}
	eventsAfterFirst := len(rec.events)

	for _, over := range []int64{60000, 40001} {
		if _, _, err := s.Refund(ctx, p.ID, money.MustNew(over, "USD")); !errors.Is(err, ErrRefundExceedsRemaining) {
			t.Fatalf("refund %d: error = %v, want ErrRefundExceedsRemaining", over, err)
		}
	}

	got, err := s.Get(ctx, p.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.Status != StatusSucceeded || got.Refunded != 60000 || got.Remaining().Minor != 40000 || len(got.Refunds) != 1 || got.Version != p.Version {
		t.Fatalf("payment mutated after rejected refund: %+v", got)
	}
	if len(rec.events) != eventsAfterFirst {
		t.Fatalf("events emitted on rejected refund: %v", rec.events)
	}

	got, _, err = s.Refund(ctx, p.ID, money.MustNew(40000, "USD"))
	if err != nil {
		t.Fatal(err)
	}
	if got.Status != StatusRefunded || got.Refunded != 100000 || got.Remaining().Minor != 0 || len(got.Refunds) != 2 {
		t.Fatalf("after exact remaining refund: %+v", got)
	}
	if _, _, err := s.Refund(ctx, p.ID, money.MustNew(1, "USD")); !errors.Is(err, ErrInvalidTransition) {
		t.Fatalf("refund after REFUNDED: error = %v, want ErrInvalidTransition", err)
	}
}

func TestConcurrentRefundsNeverExceedAmount(t *testing.T) {
	s, _ := newTestService()
	ctx := context.Background()
	p := succeeded(t, s, 1000)

	var wg sync.WaitGroup
	for i := 0; i < 10; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			_, _, _ = s.Refund(ctx, p.ID, money.MustNew(600, "USD"))
		}()
	}
	wg.Wait()

	got, err := s.Get(ctx, p.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.Refunded > got.Amount.Minor || got.Remaining().Minor < 0 {
		t.Fatalf("refunds exceeded amount: refunded=%d remaining=%d", got.Refunded, got.Remaining().Minor)
	}
}

