func TestRefundCannotExceedRemaining(t *testing.T) {
	a := newTestAPI(t)
	p := a.createSucceeded("1000.00", "USD")

	rec := a.do("POST", "/payments/"+p.ID+"/refunds", `{"amount":"600.00"}`)
	if rec.Code != http.StatusCreated {
		t.Fatalf("first refund: %d %s", rec.Code, rec.Body)
	}
	first := decode[paymentResponse](t, rec)
	if first.RefundedAmount != "600.00" || first.RemainingAmount != "400.00" || first.Status != "SUCCEEDED" || len(first.Refunds) != 1 {
		t.Fatalf("after first refund %+v", first)
	}

	for _, amt := range []string{"600.00", "400.01"} {
		rec = a.do("POST", "/payments/"+p.ID+"/refunds", `{"amount":"`+amt+`"}`)
		if rec.Code != http.StatusUnprocessableEntity {
			t.Fatalf("over refund %s: status %d, want 422: %s", amt, rec.Code, rec.Body)
		}
		if e := decode[errorBody](t, rec); e.Error.Code != "refund_exceeds_remaining" {
			t.Fatalf("over refund %s: code %q, want refund_exceeds_remaining", amt, e.Error.Code)
		}
	}

	unchanged := decode[paymentResponse](t, a.do("GET", "/payments/"+p.ID, ""))
	if unchanged.RefundedAmount != "600.00" || unchanged.RemainingAmount != "400.00" || unchanged.Status != "SUCCEEDED" || len(unchanged.Refunds) != 1 {
		t.Fatalf("payment changed after rejected refund: %+v", unchanged)
	}

	rec = a.do("POST", "/payments/"+p.ID+"/refunds", `{"amount":"400.00"}`)
	if rec.Code != http.StatusCreated {
		t.Fatalf("exact remaining refund: %d %s", rec.Code, rec.Body)
	}
	full := decode[paymentResponse](t, rec)
	if full.RefundedAmount != "1000.00" || full.RemainingAmount != "0.00" || full.Status != "REFUNDED" || len(full.Refunds) != 2 {
		t.Fatalf("after full refund %+v", full)
	}
}

