		t.Fatal(err)
	}
	if got.Status != StatusSucceeded || got.Refunded != 60000 || got.Remaining().Minor != 40000 || len(got.Refunds) != 1 || got.Version != p.Version {
		t.Fatalf("payment mutated after rejected refund: %+v", got)
	}
	if len(rec.events) != eventsAfterFirst {
		t.Fatalf("events emitted on rejected refund: %v", rec.events)
	}

	got, _, err = s.Refund(ctx, p.ID, money.MustNew(40000, "USD"))
	if err != nil {
		t.Fatal(err)
	}
	if got.Status != StatusRefunded || got.Refunded != 100000 || got.Remaining().Minor != 0 || len(got.Refunds) != 2 {
		t.Fatalf("after exact remaining refund: %+v", got)
	}
	if _, _, err := s.Refund(ctx, p.ID, money.MustNew(1, "USD")); !errors.Is(err, ErrInvalidTransition) {
		t.Fatalf("refund after REFUNDED: error = %v, want ErrInvalidTransition", err)
	}
}

func TestConcurrentRefundsNeverExceedAmount(t *testing.T) {
	s, _ := newTestService()
	ctx := context.Background()
	p := succeeded(t, s, 1000)

	var wg sync.WaitGroup
	for i := 0; i < 10; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			_, _, _ = s.Refund(ctx, p.ID, money.MustNew(600, "USD"))
		}()
	}
	wg.Wait()

	got, err := s.Get(ctx, p.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.Refunded > got.Amount.Minor || got.Remaining().Minor < 0 {
		t.Fatalf("refunds exceeded amount: refunded=%d remaining=%d", got.Refunded, got.Remaining().Minor)
	}
}

